window.bookSummaryJSON = "<p><i>Fingerprints of the Gods</i> is the revolutionary rewrite of history that has persuaded millions of listeners throughout the world to change their preconceptions about the history behind modern society. </p> <p>An intellectual detective story, this unique history audiobook directs probing questions at orthodox history, presenting disturbing new evidence that historians have tried - but failed - to explain. </p>"; 
